'use strict';
function victoryState(){state.victory??={won:false,dismissed:false};return state.victory}
function victoryProgress(){const towns=state.towns||[],forts=islandLife().forts,enemies=riverAdventure().enemies;return {towns:towns.filter(t=>t.relation==='conquered').length,totalTowns:towns.length,forts:forts.filter(f=>['cleared','owned'].includes(f.phase)).length,ships:enemies.filter(e=>e.hp<=0).length,totalShips:Math.max(3,enemies.length),castle:castleLevel()>=2}}
function victoryReady(){const p=victoryProgress();return p.totalTowns>0&&p.towns===p.totalTowns&&(isDesertCampaign()||p.forts>=5&&p.ships>=p.totalShips&&p.castle)}
function victoryChecklist(){const p=victoryProgress();if(isDesertCampaign())return '<p>'+(p.totalTowns>0&&p.towns===p.totalTowns?'✓':'○')+' Przejmij wszystkie obozy orków: <b>'+p.towns+'/'+p.totalTowns+'</b></p><p>✓ Dolina ukończona — osady, piraci i zamek</p>';return '<p>'+(p.totalTowns>0&&p.towns===p.totalTowns?'✓':'○')+' Przejmij wszystkie osady: <b>'+p.towns+'/'+p.totalTowns+'</b></p><p>'+(p.forts>=5?'✓':'○')+' Pokonaj załogi pirackich twierdz: <b>'+p.forts+'/5</b></p><p>'+(p.ships>=p.totalShips?'✓':'○')+' Zniszcz lub zdobądź pirackie łodzie: <b>'+p.ships+'/'+p.totalShips+'</b></p><p>'+(p.castle?'✓':'○')+' Zbuduj zamek: <b>'+(p.castle?'gotowy':'domek → dwór → zamek')+'</b></p>'}
function checkWorldVictory(){if(!victoryReady())return false;return awardWorldVictory()}
function awardWorldVictory(){const v=victoryState();if(v.won)return false;v.won=true;v.wonAt=state.time;v.wasPaused=!!state.clock.paused;state.clock.paused=true;keys={};target=null;renderClock();save();renderVictory(true);return true}
function continueAfterVictory(){const v=victoryState();if(!v.won)return false;v.dismissed=true;state.clock.paused=!!v.wasPaused;worldVictory.style.display='none';renderClock();save();return true}
const worldVictory=document.createElement('div');worldVictory.id='worldVictory';worldVictory.setAttribute('role','dialog');worldVictory.setAttribute('aria-modal','true');worldVictory.setAttribute('aria-label','Zwycięstwo');worldVictory.style.cssText='display:none;position:fixed;inset:0;z-index:300;background:#10261fdd;align-items:center;justify-content:center;padding:20px;backdrop-filter:blur(6px)';worldVictory.innerHTML='<article style="width:560px;text-align:center;border-color:#e1c379"><div style="font-size:64px">🏆</div><h1 id="victoryTitle">Zwycięstwo!</h1><p id="victoryDescription">Cała dolina należy do Ciebie. Osady zostały zjednoczone, piraci pokonani, a Twój zamek góruje nad królestwem.</p><div id="victorySummary" style="text-align:left;line-height:1.8"></div><button id="desertStart" style="width:100%;margin-bottom:10px;background:#d4bc75;color:#21392d;font-weight:bold">Rozpocznij etap II — Pustynia orków →</button><button id="victoryContinue" style="width:100%;background:#d4bc75;color:#21392d;font-weight:bold">Graj dalej w swoim królestwie</button><small>Wygrana zostaje zapisana. Możesz dalej budować i odkrywać mapę.</small></article>';document.body.append(worldVictory);$('victoryContinue').onclick=continueAfterVictory;$('desertStart').onclick=startDesertCampaign;
const victoryPanel=document.createElement('aside');victoryPanel.id='victoryPanel';victoryPanel.className='war-panel hidden';victoryPanel.innerHTML='<div class="war-title"><h2>Droga do zwycięstwa</h2><button id="victoryClose">✕</button></div><div id="victoryProgress"></div><button id="desertStartPanel" style="display:none">Rozpocznij etap II — Pustynia orków →</button><div id="victoryHelp"><p>Wszystkie warunki muszą być spełnione jednocześnie. Sojusz nie oznacza przejęcia osady. Pokonaną twierdzę możesz dodatkowo przejąć, ale do zwycięstwa wystarczy pokonać jej załogę.</p><p>Twierdze: panel „Osady, światło i piraci”. Pirackie łodzie: rozpocznij „Wyprawy rzeczne”. Zamek: „Osady i wojsko” → „Dowodzenie” → „Królestwo”.</p></div>';document.body.append(victoryPanel);const victoryOpen=document.createElement('button');victoryOpen.textContent='🏆 Cel gry';victoryOpen.onclick=()=>{$('victoryPanel').classList.remove('hidden');renderVictory(true)};$('clockControls').append(victoryOpen);$('victoryClose').onclick=()=>$('victoryPanel').classList.add('hidden');
$('desertStartPanel').onclick=startDesertCampaign;let victorySignature='';function renderVictory(force=false){const v=victoryState(),signature=JSON.stringify([victoryProgress(),v.won,isDesertCampaign()]);if(force||signature!==victorySignature){victorySignature=signature;const desert=isDesertCampaign();$('victoryTitle').textContent=desert?'Ostateczne zwycięstwo!':'Zwycięstwo w dolinie!';$('victoryDescription').textContent=desert?'Dolina została zjednoczona, piraci pokonani, a wszystkie obozy orków przejęte. Ukończono oba etapy gry!':'Dolina jest Twoja! Teraz czeka Cię nowa gra na pustyni. Rozpoczniesz od małego domku i zapasów, a zamiast osad spotkasz 100 obozów orków. Kopia ukończonej doliny zostanie zachowana.';$('desertStart').style.display=!desert&&v.won?'block':'none';$('desertStartPanel').style.display=!desert&&v.won?'block':'none';$('victoryHelp').style.display=desert?'none':'block';$('victoryProgress').innerHTML=(v.won?'<h3>🏆 Gra wygrana!</h3>':'')+victoryChecklist();$('victorySummary').innerHTML=v.byCode?'<p>✓ Zwycięstwo odblokowane kodem 1248.</p>':victoryChecklist();if(v.byCode)$('victoryDescription').textContent=desert?'Ukończono oba etapy gry kodem zwycięstwa. Możesz dalej grać.':'Dolina ukończona kodem zwycięstwa. Możesz rozpocząć nową grę na pustyni z obozami orków.';victoryOpen.textContent=v.won?(isDesertCampaign()?'🏆 Ostateczne zwycięstwo':'🏆 Dolina ukończona'):'🏆 Cel gry'}if(v.won&&!v.dismissed)worldVictory.style.display='flex'}
const victoryUI=ui;ui=function(){victoryUI();checkWorldVictory();renderVictory()};let victoryCheckTimer=0;const victoryStep=simulationStep;simulationStep=function(dt){victoryStep(dt);victoryCheckTimer+=dt;if(victoryCheckTimer>=1){victoryCheckTimer=0;checkWorldVictory()}};window.addEventListener('keydown',e=>{if(e.key==='Escape')$('victoryPanel').classList.add('hidden')});checkWorldVictory();renderVictory(true);
